mapper.select:
SELECT type_id AS typeId, team_id AS teamId, project_id AS projectId, type_name AS typeName,
       sort_order AS sortOrder, enabled AS enabled
FROM sys_case_type WHERE type_id = #{typeId}

SELECT COUNT(*)
FROM sys_case c
         INNER JOIN sys_project p ON c.project_id = p.project_id
WHERE p.team_id = #{teamId}
  AND c.case_type = #{typeId}
